#include <iostream>
#include <fstream>
#include <memory>

class FileHandler {
public:
  FileHandler(const std::string& filename) : file_(filename.c_str(), std::ios::out) {
    if (!file_) {
      throw std::runtime_error("Could not open file");
    }
  }
  ~FileHandler() { file_.close(); } // Resource released in destructor
  std::ofstream& get_file() { return file_; }
private:
  std::ofstream file_;
};

int main() {
  try {
    FileHandler file("mydata.txt");
    file.get_file() << "This is some data\n";
  } catch (const std::runtime_error& e) {
    std::cerr << "Error: " << e.what() << std::endl;
    return 1;
  }
  return 0;
}
